        uint256 balBefore = address(c).balance;
        bool r1 = c.setOwner(address(0)); if (__ESBMC_reverted()) return;
        address afterOwner1 = c.owner(); if (__ESBMC_reverted()) return;
        bool r2 = c.setOwner(address(0)); if (__ESBMC_reverted()) return;
